struct Rectangle { width : u32 , height : u32 , } impl Rectangle { fn area (& self) -> u32 { self . width * self . height } fn scale (& mut self , factor : u32) { self . width *= factor ; self . height *= factor ; } } fn main () { let mut rect1 = Rectangle { width : 30 , height : 50 , } ; println ! ("The area of the rectangle is {} square pixels." , rect1 . area ()) ; rect1 . scale (2) ; println ! ("The area of the rectangle is now {} square pixels." , rect1 . area ()) ; rect1 . scale (2675) ; println ! ("The area of the rectangle is now {} square pixels." , rect1 . area ()) }